import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Inverting-negatively-coded-variables.md","filePath":"manual-en/Inverting-negatively-coded-variables.md","lastUpdated":1785684581000}'),n={name:"manual-en/Inverting-negatively-coded-variables.md"};function o(i,t,s,l,g,h){return e(),r("div",null,[...t[0]||(t[0]=[a(`<h4 id="_5-2-3-inverting-negatively-coded-variables" tabindex="-1">5.2.3 Inverting negatively coded variables <a class="header-anchor" href="#_5-2-3-inverting-negatively-coded-variables" aria-label="Permalink to &quot;5.2.3 Inverting negatively coded variables&quot;">​</a></h4><p>Data entry errors are not the only reason for wanting to recode data. The sample file hotel.sav comprises data gathered from a customer satisfaction survey of clients at a particular hotel. The following commands load the file and display its variables and associated data:</p><pre><code>PSPP&gt; get file=&#39;/usr/local/share/pspp/examples/hotel.sav&#39;.
PSPP&gt; display dictionary.
</code></pre><p>It yields the following output:</p><table tabindex="0"><thead><tr><th>Name</th><th>Position</th><th>Label</th><th>Measurement Level</th><th>Role</th><th>Width</th><th>Alignment</th><th>Print Format</th><th>Write Format</th></tr></thead><tbody><tr><td>v1</td><td>1</td><td>I am satisfied with the level of service</td><td>Ordinal</td><td>Input</td><td>8</td><td>Right</td><td>F8.0</td><td>F8.0</td></tr><tr><td>v2</td><td>2</td><td>The value for money was good</td><td>Ordinal</td><td>Input</td><td>8</td><td>Right</td><td>F8.0</td><td>F8.0</td></tr><tr><td>v3</td><td>3</td><td>The staff were slow in responding</td><td>Ordinal</td><td>Input</td><td>8</td><td>Right</td><td>F8.0</td><td>F8.0</td></tr><tr><td>v4</td><td>4</td><td>My concerns were dealt with in an efficient manner</td><td>Ordinal</td><td>Input</td><td>8</td><td>Right</td><td>F8.0</td><td>F8.0</td></tr><tr><td>v5</td><td>5</td><td>There was too much noise in the rooms</td><td>Ordinal</td><td>Input</td><td>8</td><td>Right</td><td>F8.0</td><td>F8.0</td></tr><tr><td>Variable Value</td><td>Label</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>I am satisfied with the level of service</td><td>1</td><td>Strongly Disagree</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td>Disagree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td>No Opinion</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td>Agree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td>Strongly Agree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>The value for money was good</td><td>1</td><td>Strongly Disagree</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td>Disagree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td>No Opinion</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td>Agree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td>Strongly Agree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>The staff were slow in responding</td><td>1</td><td>Strongly Disagree</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td>Disagree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td>No Opinion</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td>Agree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td>Strongly Agree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>My concerns were dealt with in an efficient manner</td><td>1</td><td>Strongly Disagree</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td>Disagree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td>No Opinion</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td>Agree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td>Strongly Agree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>There was too much noise in the rooms</td><td>1</td><td>Strongly Disagree</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td>Disagree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td>No Opinion</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td>Agree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td>Strongly Agree</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>The output shows that all of the variables <strong>v1</strong> through <strong>v5</strong> are measured on a 5 point Likert scale, with 1 meaning “Strongly disagree” and 5 meaning “Strongly agree”. However, some of the questions are positively worded (<strong>v1</strong> , <strong>v2</strong> , <strong>v4</strong>) and others are negatively worded (<strong>v3</strong> , <strong>v5</strong>). To perform meaningful analysis, we need to recode the variables so that they all measure in the same direction. We could use the <code>RECODE</code> command, with syntax such as:</p><pre><code>recode v3 (1 = 5) (2 = 4) (4 = 2) (5 = 1).
</code></pre><p>However an easier and more elegant way uses the <code>COMPUTE</code> command (see <a href="./COMPUTE">COMPUTE</a>). Since the variables are Likert variables in the range (1 … 5), subtracting their value from 6 has the effect of inverting them:</p><pre><code>compute var = 6 - var.
</code></pre><p>The following section uses this technique to recode the variables <strong>v3</strong> and <strong>v5</strong>. After applying <code>COMPUTE</code> for both variables, all subsequent commands will use the inverted values.</p>`,10)])])}const p=d(n,[["render",o]]);export{v as __pageData,p as default};
